<title>Why Is the Sky Blue? · 天空为什么是蓝色的？</title>
<style>
  :root{
    --bg1:#0b1e3f; --bg2:#274b8d; --ink:#1c2430; --muted:#5b6675;
    --card:#ffffff; --accent:#2f7fe0; --accent2:#f0a500; --line:#e4e9f0;
    --en:#1b3a6b; --zh:#a4560c;
  }
  *{box-sizing:border-box;}
  html,body{margin:0;padding:0;height:100%;}
  body{
    font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,
      "PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;
    color:var(--ink);
    background:linear-gradient(135deg,var(--bg1),var(--bg2));
    background-attachment:fixed;
    display:flex;flex-direction:column;min-height:100vh;overflow:hidden;
  }
  header{
    color:#fff;text-align:center;padding:18px 16px 10px;
  }
  header h1{margin:0;font-size:clamp(20px,3.4vw,34px);letter-spacing:.5px;font-weight:700;}
  header .sub{margin-top:4px;font-size:clamp(13px,1.8vw,16px);opacity:.85;}
  header .badge{
    display:inline-block;margin-top:10px;padding:5px 14px;border-radius:999px;
    background:rgba(255,255,255,.14);font-size:12px;letter-spacing:1px;text-transform:uppercase;
  }

  main{
    flex:1;display:flex;align-items:stretch;justify-content:center;
    padding:8px 22px 6px;min-height:0;
  }
  .deck{width:100%;max-width:1180px;display:flex;flex-direction:column;min-height:0;}

  .slide{
    display:none;flex:1;min-height:0;
    grid-template-columns:1fr 1fr;gap:18px;
    animation:fade .45s ease;
  }
  .slide.active{display:grid;}
  @keyframes fade{from{opacity:0;transform:translateY(10px);}to{opacity:1;transform:none;}}

  .col{
    background:var(--card);border-radius:16px;padding:24px 26px;overflow-y:auto;
    box-shadow:0 12px 40px rgba(0,0,0,.28);border-top:6px solid var(--accent);
    min-height:0;
  }
  .col.zh{border-top-color:var(--accent2);}
  .lang-tag{
    display:inline-block;font-size:11px;font-weight:700;letter-spacing:1.5px;text-transform:uppercase;
    padding:4px 10px;border-radius:6px;margin-bottom:12px;color:#fff;background:var(--accent);
  }
  .col.zh .lang-tag{background:var(--accent2);}
  .audience{
    margin:0 0 14px;font-size:clamp(17px,2.1vw,22px);color:var(--en);font-weight:700;
  }
  .col.zh .audience{color:var(--zh);}
  .col p{line-height:1.7;margin:0 0 13px;font-size:clamp(14px,1.55vw,16.5px);color:var(--ink);}
  .col ul{margin:0 0 13px;padding-left:20px;line-height:1.7;font-size:clamp(14px,1.55vw,16px);}
  .col li{margin-bottom:9px;}
  .col strong{color:#0f2d57;}
  .col.zh strong{color:#8a4708;}
  .col em{color:var(--muted);font-style:italic;}
  .col h3{font-size:14px;margin:16px 0 6px;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;}
  code,.m{font-family:"SFMono-Regular",Consolas,"Liberation Mono",Menlo,monospace;
    background:#f2f5fa;padding:1px 5px;border-radius:4px;font-size:.92em;color:#123;}

  /* native equation rendering (no external libs) */
  .eq{
    text-align:center;margin:16px 0;font-size:clamp(16px,2vw,20px);color:#0f2d57;
    background:#f6f9fd;border:1px solid var(--line);border-radius:10px;padding:14px 10px;
  }
  .eq .frac,.frac{display:inline-flex;flex-direction:column;vertical-align:middle;
    text-align:center;margin:0 4px;line-height:1.15;}
  .frac .num{border-bottom:2px solid currentColor;padding:0 6px 1px;}
  .frac .den{padding:1px 6px 0;}
  .var{font-style:italic;font-family:"Cambria Math","Times New Roman",serif;}
  sup,sub{font-size:.72em;}

  footer{
    color:#fff;display:flex;align-items:center;justify-content:center;gap:18px;
    padding:14px 18px 20px;flex-wrap:wrap;
  }
  .nav-btn{
    border:none;cursor:pointer;font-size:15px;font-weight:600;color:#fff;
    background:rgba(255,255,255,.16);padding:10px 20px;border-radius:999px;
    transition:background .2s,transform .1s;
  }
  .nav-btn:hover{background:rgba(255,255,255,.32);}
  .nav-btn:active{transform:scale(.95);}
  .dots{display:flex;gap:9px;}
  .dot{width:11px;height:11px;border-radius:50%;background:rgba(255,255,255,.35);
    cursor:pointer;transition:background .2s,transform .2s;}
  .dot.active{background:#fff;transform:scale(1.3);}
  .counter{min-width:64px;text-align:center;font-size:14px;opacity:.9;}
  .hint{font-size:12px;opacity:.6;}

  /* title slide */
  .title-wrap{
    flex:1;display:flex;flex-direction:column;align-items:center;justify-content:center;
    text-align:center;color:#fff;gap:10px;
  }
  .title-wrap .big{font-size:clamp(34px,7vw,72px);font-weight:800;line-height:1.1;
    background:linear-gradient(90deg,#bfe0ff,#fff,#ffd27a);-webkit-background-clip:text;
    background-clip:text;color:transparent;}
  .title-wrap .c1{font-size:clamp(20px,3vw,30px);color:#ffe1a3;}
  .title-wrap .lead{max-width:680px;opacity:.9;font-size:clamp(14px,1.8vw,17px);line-height:1.6;}
  .title-wrap .start{margin-top:14px;}
  .title-slide{display:none;flex:1;grid-template-columns:1fr;}
  .title-slide.active{display:grid;}

  @media (max-width:780px){
    body{overflow:auto;}
    main{padding:6px 12px;}
    .slide.active{grid-template-columns:1fr;overflow-y:auto;}
    .col{max-height:none;}
  }
</style>
</head>
<body>

<header>
  <h1>Why Is the Sky Blue?</h1>
  <div class="sub">天空为什么是蓝色的？</div>
  <div class="badge">Bilingual Slide Deck · 双语幻灯片</div>
</header>

<main>
  <div class="deck">

    <!-- TITLE SLIDE -->
    <section class="slide title-slide active" id="s0">
      <div class="title-wrap">
        <div class="big">Why Is the Sky Blue?</div>
        <div class="c1">天空为什么是蓝色的？</div>
        <p class="lead">The same question, explained three ways — for a 3-year-old, a high-schooler, and a physics PhD — with English and 简体中文 shown side by side.<br>
        同一个问题，三种讲法——给 3 岁宝宝、高中生和物理学博士——英文与简体中文并排呈现。</p>
        <button class="nav-btn start" onclick="go(1)">Start ▶ 开始</button>
      </div>
    </section>

    <!-- SLIDE 1 : TODDLER -->
    <section class="slide" id="s1">
      <div class="col en">
        <span class="lang-tag">English</span>
        <h2 class="audience">For a 3-Year-Old Toddler</h2>
        <p>The sky is blue because of the sun! ☀️</p>
        <p>The sun shines light down to us. That light looks white, but it's actually made of all the colors of the rainbow — red, orange, yellow, green, blue, and more! 🌈</p>
        <p>Up in the sky there are tiny, tiny bits of air. When the sun's light hits them, the blue color gets knocked all around and splashed everywhere — like when you scatter bubbles in the bath! The blue goes <em>everywhere</em>, so when you look up, you see blue all over. Pretty, right?</p>
      </div>
      <div class="col zh">
        <span class="lang-tag">中文</span>
        <h2 class="audience">给 3 岁的小宝宝</h2>
        <p>天空是蓝色的，都怪太阳公公！☀️</p>
        <p>太阳把光洒到我们身上。这些光看起来是白色的，可其实它是由彩虹里所有的颜色组成的——红色、橙色、黄色、绿色、蓝色，还有好多好多！🌈</p>
        <p>天上有很多很多非常非常小的空气小颗粒。太阳的光撞上去的时候，蓝色就会被撞得到处乱跑、到处乱溅——就像你在浴缸里把泡泡拍得到处飞一样！蓝色跑得到处都是，所以你抬头一看，满眼都是蓝色。漂亮吧？</p>
      </div>
    </section>

    <!-- SLIDE 2 : TEENAGER -->
    <section class="slide" id="s2">
      <div class="col en">
        <span class="lang-tag">English</span>
        <h2 class="audience">For a High School Teenager</h2>
        <p>Sunlight looks white, but it's a mixture of electromagnetic waves of many different wavelengths, which our eyes perceive as different colors. Red light has a long wavelength (around 700 nm), while blue and violet light have much shorter wavelengths (around 400–450 nm).</p>
        <p>When sunlight enters Earth's atmosphere, it collides with molecules of nitrogen and oxygen. These molecules are much smaller than the wavelength of visible light, so they scatter the light. This is called <strong>Rayleigh scattering</strong>, and here's the key part: the amount of scattering is <em>inversely proportional to the fourth power of the wavelength</em> — often written as:</p>
        <div class="eq"><span class="var">I</span> ∝ <span class="frac"><span class="num">1</span><span class="den"><span class="var">λ</span><sup>4</sup></span></span></div>
        <p>This means short-wavelength light (blue) gets scattered far more strongly than long-wavelength light (red). So when you look up away from the sun, your eyes receive mostly this scattered blue light coming from all directions, and the sky appears blue. Red light, by contrast, passes mostly straight through the atmosphere.</p>
        <h3>A couple of common follow-ups</h3>
        <ul>
          <li><em>Why isn't the sky violet, since violet scatters even more than blue?</em> Two reasons: the sun emits less violet light, and human eyes are much less sensitive to violet. The blue signal dominates.</li>
          <li><em>Why are sunsets red?</em> When the sun is low, its light travels through much more atmosphere. Most of the blue gets scattered away before reaching your eyes, leaving the warm reds and oranges.</li>
        </ul>
      </div>
      <div class="col zh">
        <span class="lang-tag">中文</span>
        <h2 class="audience">给高中生</h2>
        <p>太阳光看起来是白色的，但它其实是许多不同波长的电磁波的混合，我们的眼睛会把这些不同波长感知成不同的颜色。红光的波长比较长（约 700 纳米），而蓝光和紫光的波长要短得多（约 400–450 纳米）。</p>
        <p>当太阳光进入地球大气层时，会与氮气、氧气的分子发生碰撞。这些分子比可见光的波长小得多，于是会把光散射开来。这叫作<strong>瑞利散射（Rayleigh scattering）</strong>，关键在于：散射的强弱<em>与波长的四次方成反比</em>——通常写成：</p>
        <div class="eq"><span class="var">I</span> ∝ <span class="frac"><span class="num">1</span><span class="den"><span class="var">λ</span><sup>4</sup></span></span></div>
        <p>这意味着波长较短的光（蓝色）比波长较长的光（红色）被散射得强烈得多。所以当你抬头看向远离太阳的方向时，你的眼睛接收到的主要是从四面八方散射过来的蓝色光，天空就显得是蓝色的。相比之下，红光大多直接穿过大气层照过来。</p>
        <h3>几个常见的追问</h3>
        <ul>
          <li><em>既然紫光比蓝光散射得更多，天空为什么不是紫色的？</em> 有两个原因：太阳发出的紫光较少，而且人眼对紫光的敏感度要低得多。于是蓝色的信号占了主导。</li>
          <li><em>为什么日落时是红色的？</em> 当太阳位置很低时，它的光要穿过厚得多的大气层。大部分蓝光在到达你的眼睛之前就被散射掉了，于是留下了温暖的红色和橙色。</li>
        </ul>
      </div>
    </section>

    <!-- SLIDE 3 : PhD -->
    <section class="slide" id="s3">
      <div class="col en">
        <span class="lang-tag">English</span>
        <h2 class="audience">For a Physics PhD</h2>
        <p>The blue sky is a manifestation of <strong>elastic Rayleigh scattering</strong> of solar radiation by atmospheric molecules whose polarizability is excited well below any electronic resonance.</p>
        <p>For a particle small compared to the wavelength (<span class="var">a</span> ≪ <span class="var">λ</span>, size parameter <span class="var">x</span> = 2<span class="var">πa</span>/<span class="var">λ</span> ≪ 1), the differential scattering cross-section follows from the induced-dipole radiation pattern:</p>
        <div class="eq">
          <span class="frac"><span class="num">d<span class="var">σ</span></span><span class="den">dΩ</span></span> =
          <span class="frac"><span class="num"><span class="var">k</span><sup>4</sup><span class="var">α</span><sup>2</sup></span><span class="den">16<span class="var">π</span><sup>2</sup><span class="var">ε</span><sub>0</sub><sup>2</sup></span></span>
          (1 + cos<sup>2</sup><span class="var">θ</span>)
        </div>
        <p>Integrating over solid angle gives the total cross-section <span class="var">σ</span> ∝ <span class="var">ω</span><sup>4</sup> ∝ <span class="var">λ</span><sup>−4</sup>, which is the <span class="var">λ</span><sup>−4</sup> dependence behind the sky's color. For dry air at STP the volume scattering coefficient is dominated by N<sub>2</sub> and O<sub>2</sub>, and the relevant depolarization factor (from anisotropic polarizability) modestly modifies the pure 1 + cos<sup>2</sup><span class="var">θ</span> phase function.</p>
        <p>Several subtleties deserve note:</p>
        <ul>
          <li><strong>Multiple scattering and the aureole.</strong> Single-scattering theory gives the first-order hue, but the full radiance field, including the forward-scattering aureole near the sun and polarization patterns (the 90° maximum polarization used historically by navigation-inclined insects and by Rayleigh himself), requires solving the radiative transfer equation with the appropriate phase matrix.</li>
          <li><strong>Absorption bands.</strong> The solar spectrum is not a blackbody at 5778 K exactly; Fraunhofer lines, O<sub>3</sub> (Chappuis/Huggins) and H<sub>2</sub>O absorption modify the incident spectral irradiance and shift the perceived chromaticity slightly away from a naive <span class="var">λ</span><sup>−4</sup>-weighted spectrum.</li>
          <li><strong>Why not violet.</strong> The violet scattering advantage (~ (430/400)<sup>4</sup>) is outweighed by lower solar spectral radiance in the violet, strong O<sub>3</sub> Huggins absorption in the near-UV/violet, and the <span class="var">S</span>-cone response of the human visual system, which has low sensitivity below ~420 nm. CIE chromaticity integration over the incident spectrum × cross-section × CMF yields a perceived blue, not violet.</li>
          <li><strong>Aerosols and the transition to Mie.</strong> When the size parameter <span class="var">x</span> ≳ 1 (aerosols, water droplets, pollution), scattering becomes weakly wavelength-dependent and forward-peaked (Mie regime), washing out the blue and producing whitish haze — and in the <span class="var">x</span> ≫ 1 limit, wavelength-independent geometric scattering, which is why clouds are white and heavily polluted skies appear grey.</li>
          <li><strong>Sunset reds.</strong> At low solar elevation the slant path optical depth <span class="var">τ</span>(<span class="var">λ</span>) ∝ <span class="var">λ</span><sup>−4</sup> sec <span class="var">z</span> (with refraction and curvature corrections) preferentially extinguishes blue via single scattering out of the direct beam, so the direct and circumsolar radiance is red-shifted; volcanic aerosols (large <span class="var">a</span>) enhance this via combined extinction.</li>
        </ul>
        <p>In short: the observed sky color is the convolution of the solar spectrum, the <span class="var">λ</span><sup>−4</sup> molecular scattering kernel and its phase function, atmospheric absorption, multiple-scattering radiative transfer, and the spectral response of human photoreceptors.</p>
      </div>
      <div class="col zh">
        <span class="lang-tag">中文</span>
        <h2 class="audience">给物理学博士</h2>
        <p>蓝天是大气分子对太阳辐射发生<strong>弹性瑞利散射</strong>的一种表现；这些分子的极化率被激发时所处的能量远低于任何电子共振。</p>
        <p>对于尺寸远小于波长的粒子（<span class="var">a</span> ≪ <span class="var">λ</span>，尺寸参量 <span class="var">x</span> = 2<span class="var">πa</span>/<span class="var">λ</span> ≪ 1），其微分散射截面可由感应偶极子的辐射图样导出：</p>
        <div class="eq">
          <span class="frac"><span class="num">d<span class="var">σ</span></span><span class="den">dΩ</span></span> =
          <span class="frac"><span class="num"><span class="var">k</span><sup>4</sup><span class="var">α</span><sup>2</sup></span><span class="den">16<span class="var">π</span><sup>2</sup><span class="var">ε</span><sub>0</sub><sup>2</sup></span></span>
          (1 + cos<sup>2</sup><span class="var">θ</span>)
        </div>
        <p>对立体角积分可得总截面 <span class="var">σ</span> ∝ <span class="var">ω</span><sup>4</sup> ∝ <span class="var">λ</span><sup>−4</sup>，这正是天空颜色背后所依据的 <span class="var">λ</span><sup>−4</sup> 依赖关系。对于标准温压（STP）下的干空气，体积散射系数主要由 N<sub>2</sub> 和 O<sub>2</sub> 决定；而相关的去极化因子（源于各向异性的极化率）会在一定程度上修正纯粹的 1 + cos<sup>2</sup><span class="var">θ</span> 相函数。</p>
        <p>有几处微妙之处值得一提：</p>
        <ul>
          <li><strong>多次散射与晕（aureole）。</strong>单次散射理论给出一阶的色相，但完整的辐射亮度场——包括太阳附近的正向散射晕以及偏振图样（历史上被善于导航的昆虫以及瑞利本人所利用的、在 90° 处的最大偏振）——需要借助适当的相矩阵求解辐射传输方程。</li>
          <li><strong>吸收带。</strong>太阳光谱并非严格意义上的 5778 K 黑体；夫琅禾费线、O<sub>3</sub>（Chappuis/Huggins 带）以及 H<sub>2</sub>O 的吸收会改变入射光谱辐照度，使感知到的色度略微偏离朴素的 <span class="var">λ</span><sup>−4</sup> 加权光谱。</li>
          <li><strong>为何不是紫色。</strong>紫光的散射优势（约为 (430/400)<sup>4</sup>）被以下因素抵消：太阳在紫波段的谱辐射亮度较低、近紫外/紫波段有强烈的 O<sub>3</sub> Huggins 吸收，以及人眼视觉系统的 <span class="var">S</span> 锥响应在约 420 nm 以下敏感度很低。将入射光谱 × 散射截面 × 颜色匹配函数（CMF）在 CIE 色度上积分，得到的感知是蓝色，而非紫色。</li>
          <li><strong>气溶胶与向米氏散射的转变。</strong>当尺寸参量 <span class="var">x</span> ≳ 1 时（气溶胶、水滴、污染颗粒），散射对波长的依赖变弱并呈前向增强（米氏散射区域），从而冲淡蓝色、形成发白的霾——而在 <span class="var">x</span> ≫ 1 的极限下，变为与波长无关的几何散射，这正是云呈白色、严重污染的灰霾天空呈灰色的原因。</li>
          <li><strong>日落的红色。</strong>当太阳仰角很低时，斜程光学厚度 <span class="var">τ</span>(<span class="var">λ</span>) ∝ <span class="var">λ</span><sup>−4</sup> sec <span class="var">z</span>（需加折射与地球曲率修正）会通过单次散射把蓝光从直射光束中优先消光掉，于是直射与太阳周围（circumsolar）的辐射亮度发生红移；火山气溶胶（<span class="var">a</span> 较大）会通过综合消光效应进一步增强这一效果。</li>
        </ul>
        <p>简而言之：我们所观测到的天空颜色，是太阳光谱、<span class="var">λ</span><sup>−4</sup> 分子散射核及其相函数、大气吸收、多次散射的辐射传输，以及人眼感光细胞光谱响应这几者的卷积结果。</p>
      </div>
    </section>

  </div>
</main>

<footer>
  <button class="nav-btn" onclick="go(-1)">◀ Prev</button>
  <div class="dots" id="dots"></div>
  <div class="counter" id="counter">1 / 4</div>
  <button class="nav-btn" onclick="go(1)">Next ▶</button>
  <div class="hint">← → arrow keys · ← → 方向键</div>
</footer>

<script>
  var total = 4;         // title + 3 audience slides
  var current = 0;
  var slides = [];
  for (var i = 0; i < total; i++){ slides.push(document.getElementById('s' + i)); }

  var dotsWrap = document.getElementById('dots');
  var counter  = document.getElementById('counter');
  for (var d = 0; d < total; d++){
    (function(idx){
      var el = document.createElement('span');
      el.className = 'dot';
      el.onclick = function(){ show(idx); };
      dotsWrap.appendChild(el);
    })(d);
  }
  var dots = dotsWrap.children;

  function show(n){
    if (n < 0) n = 0;
    if (n > total - 1) n = total - 1;
    current = n;
    for (var i = 0; i < total; i++){
      slides[i].classList.remove('active');
      dots[i].classList.remove('active');
    }
    slides[current].classList.add('active');
    dots[current].classList.add('active');
    counter.textContent = (current + 1) + ' / ' + total;
    // scroll the active column back to top
    var cols = slides[current].querySelectorAll('.col');
    for (var c = 0; c < cols.length; c++){ cols[c].scrollTop = 0; }
  }

  // go(±1) = step, go(n>=2) = jump to absolute index via start button
  function go(delta){
    if (delta === 1 && current === 0 && document.getElementById('s0').classList.contains('active')){
      show(1); return;
    }
    show(current + delta);
  }

  document.addEventListener('keydown', function(e){
    if (e.key === 'ArrowRight' || e.key === 'PageDown'){ e.preventDefault(); go(1); }
