  var counter = document.getElementById('counter');
  for (var d = 0; d < total; d++){
    (function(idx){
      var el = document.createElement('span');
      el.className = 'dot'; el.onclick = function(){ show(idx); };
      dotsWrap.appendChild(el);
    })(d);
  }
  var dots = dotsWrap.children;

  function show(n){
    if (n < 0) n = 0; if (n > total - 1) n = total - 1;
    current = n;
    for (var i = 0; i < total; i++){
      slides[i].classList.remove('active');
      dots[i].classList.remove('active');
    }
    slides[current].classList.add('active');
    dots[current].classList.add('active');
    counter.textContent = (current + 1) + ' / ' + total;
    var c = slides[current].querySelector('.card'); if (c){ c.scrollTop = 0; }
  }
  // In RTL, "التالي" (next) is mapped to +1 via go(1)
  function go(delta){ show(current + delta); }

  document.addEventListener('keydown', function(e){
    if (e.key === 'ArrowLeft' || e.key === 'PageDown'){ e.preventDefault(); go(1); }
    else if (e.key === 'ArrowRight' || e.key === 'PageUp'){ e.preventDefault(); go(-1); }
    else if (e.key === 'Home'){ show(0); } else if (e.key === 'End'){ show(total - 1); }
