                        modifier = Modifier.size(24.dp)
                    )
                }

                val currentMaxWidth = screenMaxWidth
                val sliderHeight = (currentMaxWidth * (4f / 3f)) * 0.25f
                Box(
                    modifier = Modifier
                        .align(Alignment.TopEnd)
                        .padding(end = 16.dp, top = 40.dp)
